const raw = $input.first().json.body || $input.first().json;
if (raw.event === 'new_academic_task' && raw.task) {
  return [{
    json: {
      mode: 'pre_extracted',
      task: raw.task,
      calendar: raw.calendar || null,
      filename: raw.task.source_file || 'task.txt',
      received_at: new Date().toISOString()
    }
  }];
}

const text = String(raw.content || raw.text || '').trim();
if (!text) {
  throw new Error('Webhook payload must contain either task text (content/text) or a pre-extracted task object.');
}

const baseUrl = ($env.ACADEMIC_LLM_API_BASE || $env.ROUTER_API_BASE || 'http://127.0.0.1:20128/v1').replace(/\/+$/, '');
const model = $env.ROUTER_MODEL || 'gpt-4o-mini';
const filename = String(raw.filename || raw.file_name || 'document.txt');
const systemPrompt = 'Extract structured academic tasks from text in Indonesian or English. Return ONLY raw JSON: {"is_academic":true,"kind":"assignment|quiz|exam|syllabus|announcement|general","course":"Course","title":"Title","deadline":"YYYY-MM-DD HH:MM or null","estimated_hours":2,"priority":"HIGH|MEDIUM|LOW","summary":"Short summary","subtasks":["Step 1"],"deliverables":["PDF"]}. Default missing times to 23:59.';

return [{
  json: {
    mode: 'llm',
    llm_url: `${baseUrl}/chat/completions`,
    llm_body_json: JSON.stringify({
      model,
      stream: false,
      temperature: 0.1,
      messages: [
        { role: 'system', content: systemPrompt },
        { role: 'user', content: `Document: ${filename}\n\nContent:\n${text.slice(0, 12000)}` }
      ]
    }),
    filename,
    received_at: new Date().toISOString()
  }
}];

const resp = $input.first().json;
const rawContent = resp?.choices?.[0]?.message?.content;
if (!rawContent) {
  throw new Error('LLM endpoint did not return a valid completion message.');
}

let cleaned = String(rawContent).trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '').trim();
let task;
try {
  task = JSON.parse(cleaned);
} catch {
  const match = cleaned.match(/\{[\s\S]*\}/);
  if (!match) throw new Error('LLM output did not contain valid JSON.');
  task = JSON.parse(match[0]);
}

const course = String(task.course || 'General Course').slice(0, 200);
const title = String(task.title || 'Academic Task').slice(0, 200);
const summary = String(task.summary || 'Extracted academic task.').slice(0, 2000);
const priority = String(task.priority || 'MEDIUM').toUpperCase();
const deadline = task.deadline ? String(task.deadline).trim() : '';

const tzOffsetMinutes = 7 * 60;
let gcalUrl = '';
if (deadline) {
  const isoMatch = deadline.match(/(20\d{2})-(\d{2})-(\d{2})(?:[ T](\d{1,2})[:.](\d{2}))?/);
  if (isoMatch) {
    const [ , y, m, d, hh = '23', mm = '59' ] = isoMatch;
    const localMs = Date.UTC(Number(y), Number(m) - 1, Number(d), Number(hh), Number(mm), 0) - tzOffsetMinutes * 60 * 1000;
    const endUtc = new Date(localMs);
    const startUtc = new Date(localMs - 2 * 3600 * 1000);
    const fmt = (dt) => dt.toISOString().replace(/[-:]/g, '').replace(/\.\d{3}/, '');
    const params = new URLSearchParams({
      action: 'TEMPLATE',
      text: `[${course}] ${title}`.slice(0, 70),
      dates: `${fmt(startUtc)}/${fmt(endUtc)}`,
      details: summary.slice(0, 100),
      location: 'Online / Campus LMS'
    });
    gcalUrl = `https://calendar.google.com/calendar/render?${params.toString()}`;
    if (gcalUrl.length > 512) {
      params.delete('details');
      gcalUrl = `https://calendar.google.com/calendar/render?${params.toString()}`;
    }
  }
}

const color = priority === 'HIGH' ? 0xED4245 : (priority === 'LOW' ? 0x57F287 : 0xFEE75C);
const fields = [
  { name: 'Course', value: course || 'General Course', inline: true },
  { name: 'Deadline', value: deadline || 'Unspecified', inline: true },
  { name: 'Priority', value: priority, inline: true }
];
if (Array.isArray(task.subtasks) && task.subtasks.length > 0) {
  const list = task.subtasks.slice(0, 6).map((s) => `- ${s}`).join('\n').slice(0, 1020);
  if (list) fields.push({ name: 'Checklist', value: list, inline: false });
}

const discordPayload = {
  embeds: [{
    title: `[${course}] ${title}`.slice(0, 256),
    description: summary,
    color,
    fields,
    footer: { text: 'academic-agent | n8n workflow' }
  }]
};
if (gcalUrl && gcalUrl.length <= 512) {
  discordPayload.components = [{
    type: 1,
    components: [{
      type: 2,
      style: 5,
      label: 'Add to Google Calendar',
      url: gcalUrl
    }]
  }];
}

return [{
  json: {
    task,
    google_calendar_url: gcalUrl || null,
    discord_url: `https://discord.com/api/v10/channels/${$env.DISCORD_CHANNEL_ID}/messages`,
    discord_payload_json: JSON.stringify(discordPayload)
  }
}];
